import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;

  final ValueNotifier<int> _refreshKey = ValueNotifier<int>(0);

  static const List<Widget Function(ValueNotifier<int>)> _pageBuilders = <
    Widget Function(ValueNotifier<int>)[
    (ValueNotifier<int> refresh) => CurrencyListPage(refreshKey: refresh),
    (ValueNotifier<int> refresh) => NewsListPage(refreshKey: refresh),
    (_) => const ProfilePage(),
  ];

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  Future<void> _refreshAll() async {
    final int nextKey = _refreshKey.value + 1;
    _refreshKey.value = nextKey;
    await Future.delayed(const Duration(milliseconds: 200));
    if (_refreshKey.value == nextKey) {
      _refreshKey.value = nextKey + 1;
    }
  }

  @override
  void dispose() {
    _refreshKey.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final Widget currentPage = _pageBuilders[_selectedIndex](_refreshKey);
    final AppLocalizations loc = context.loc;

    return Scaffold(
      body: Stack(
        children: <Widget>[
          currentPage,
          Positioned(
            bottom: 16,
            right: 16,
            child: FloatingActionButton.extended(
              onPressed: _refreshAll,
              icon: const Icon(Icons.refresh),
              label: Text(loc.refreshAll),
            ),
          ),
        ],
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
              blurRadius: 25,
              offset: const Offset(0.0, 0.75),
            ),
          ],
        ),
        child: BottomNavigationBar(
          currentIndex: _selectedIndex,
          onTap: _onItemTapped,
          items: <BottomNavigationBarItem>[
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/home.png',
                isSelected: currentPage is CurrencyListPage,
              ),
              label: loc.currencyRate,
            ),
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/news.png',
                isSelected: currentPage is NewsListPage,
              ),
              label: loc.news,
            ),
            const BottomNavigationBarItem(
              icon: Icon(Icons.person),
              label: 'Profile',
            ),
          ],
        ),
      ),
    );
  }
}

class TabWidget extends StatelessWidget {
  const TabWidget({
    super.key,
    required this.assetPath,
    required this.isSelected,
  });

  final String assetPath;
  final bool isSelected;

  @override
  Widget build(BuildContext context) {
    final ThemeColors colors = context.colors;

    return SizedBox.square(
      dimension: 24,
      child: Image.asset(
        assetPath,
        color: isSelected ? colors.bottomNavBarSelectedItem : colors.bottomNavBarUnselectedItem,
      ),
    );
  }
}

