  late final List<Widget Function(ValueNotifier<int>)> _pageBuilders;

  @override
  void initState() {
    super.initState();
    _pageBuilders = <Widget Function(ValueNotifier<int>)>[
      (ValueNotifier<int> refresh) => CurrencyListPage(refreshKey: refresh),
